files.spec.yaml:
yamaa: "1.0"
type: spec
domain: TEST
keys: [ID]
input: {SRC: input.csv}
output: {path: output.csv, columns: [ID, DTM, PR, DATE]}
columns:
  - {name: ID, type: int}
  - {name: DTM, type: datetime}
  - name: PR
    type: str
    derivation: {precision: {type: datetime, source: DTM}}
  - name: DATE
    type: date
    derivation: {to_date: {source: DTM}}
rows:
  - id: records
    dataset: SRC
    derivations:
      ID: SRC.ID
      DTM: {impute: {type: datetime, source: SRC.TEXT, time: last, invalid: null}}

yamaa: "1.0"
type: spec
domain: OUT
input:
  SRC: {path: source.csv, types: {ID: str, A: str, B: date}}
  RIGHT: {path: right.csv, types: {M: date, RESULT: str}}
base: SRC
keys: [K]
output: {path: out.csv, columns: [K, V]}
columns:
  - {name: K, type: str, derivation: SRC.ID}
  - {name: A, type: str, derivation: SRC.A}
  - {name: B, type: date, derivation: SRC.B}
  - {name: V, type: str, derivation: LOOK.RESULT}
intermediates:
  - id: LOOK
    dataset: RIGHT
    key:
      M: {impute: {type: date, source: A, day: first, not_after: B, month: 1}}

yamaa: "1.0"
type: spec
domain: XX
keys: [ID]
input:
  RAW: {path: raw.csv, types: {ID: int}}
output: {path: out.csv, columns: [ID, DT]}
columns:
  - {name: ID, type: int, derivation: RAW.ID}
  - {name: DT, type: date, derivation: {to_date: {source: RAW.DTC}}}
